package sohal.lld.zerodha.user;import sohal.lld.zerodha.entity.Stock;import sohal.lld.zerodha.observer.StockObserver;import sohal.lld.zerodha.order.Order;import java.util.UUID;public class User implements StockObserver {    private final String userId;    private final String name;    private final Account account;    public User(String name, double initBalance) {        this.userId = UUID.randomUUID().toString();        this.name = name;        this.account = new Account(initBalance);    }    public void orderStatusUpdate(Order order) {        System.out.printf("[Order Notification for %s] Order %s for %s is now: %s.%n",                name, order.getOrderId(), order.getStock().getSymbol(), order.getOrderStatus());    }    public void update(Stock stock) {        System.out.printf("[Notification for %s] stock %s price updated to $%.2f%n",                this.name, stock.getSymbol(), stock.getPrice());    }    public Account getAccount() {        return account;    }    public String getUserId() {        return userId;    }    public String getName() {        return name;    }}